class ApiHandler{constructor(){this.baseUrl=CONFIG.API_BASE_URL,this.token=localStorage.getItem(CONFIG.STORAGE_KEYS.TOKEN)||""}setToken(t){this.token=t,localStorage.setItem(CONFIG.STORAGE_KEYS.TOKEN,t)}clearToken(){this.token="",localStorage.removeItem(CONFIG.STORAGE_KEYS.TOKEN)}getHeaders(){const t={"Content-Type":"application/json"};return this.token&&(t.Authorization=`Bearer ${this.token}`),t}async get(t){try{const e=await fetch(`${this.baseUrl}${t}`,{method:"GET",headers:this.getHeaders()});if(!e.ok)throw new Error(`HTTP错误: ${e.status}`);return await e.json()}catch(e){throw console.error(`GET请求失败 (${t}):`,e),e}}async post(t,e){try{const r=await fetch(`${this.baseUrl}${t}`,{method:"POST",headers:this.getHeaders(),body:JSON.stringify(e)});if(!r.ok)throw new Error(`HTTP错误: ${r.status}`);return await r.json()}catch(e){throw console.error(`POST请求失败 (${t}):`,e),e}}async put(t,e){try{const r=await fetch(`${this.baseUrl}${t}`,{method:"PUT",headers:this.getHeaders(),body:JSON.stringify(e)});if(!r.ok)throw new Error(`HTTP错误: ${r.status}`);return await r.json()}catch(e){throw console.error(`PUT请求失败 (${t}):`,e),e}}async delete(t){try{const e=await fetch(`${this.baseUrl}${t}`,{method:"DELETE",headers:this.getHeaders()});if(!e.ok)throw new Error(`HTTP错误: ${e.status}`);return await e.json()}catch(e){throw console.error(`DELETE请求失败 (${t}):`,e),e}}async login(t,e){try{const r=await this.post("/auth/login",{username:t,password:e});return r.token&&this.setToken(r.token),r}catch(t){throw console.error("登录失败:",t),t}}async register(t,e,r){try{return await this.post("/auth/register",{username:t,password:e,email:r})}catch(t){throw console.error("注册失败:",t),t}}async getUserInfo(){try{return await this.get("/users/me")}catch(t){throw console.error("获取用户信息失败:",t),t}}async getOnlineUsers(){try{return await this.get("/users/online")}catch(t){throw console.error("获取在线用户列表失败:",t),t}}async getChatHistory(t=50){try{return await this.get(`/messages?limit=${t}`)}catch(t){throw console.error("获取聊天历史记录失败:",t),t}}}